mapper.select:
SELECT * FROM (
SELECT FROM ifj_instance WHERE trigger_id = #{triggerId} AND parent_instance_id IS NULL ORDER BY id ASC
) WHERE ROWNUM <= 1

SELECT 
FROM ifj_instance

    
        AND target_type = #{targetType}
    
    
        AND target_id = #{targetId}
    
    
        AND trigger_id = #{triggerId}
    
    
        AND status = #{status}
    
    
        AND parent_instance_id IS NULL
    
    
        AND root_instance_id = #{rootInstanceId}
    
    
        AND create_time >= #{from}
    
    
        AND create_time <= #{to}
    
    
        AND (
            (target_type = 'TASK' AND EXISTS (
                SELECT 1 FROM ifj_task_definition task_definition
                WHERE task_definition.id = ifj_instance.task_definition_id
                  AND LOWER(task_definition.name) LIKE LOWER(#{name})
            ))
            OR
            (target_type = 'JOB' AND EXISTS (
                SELECT 1 FROM ifj_job_definition job_definition
                WHERE job_definition.id = ifj_instance.definition_id
                  AND LOWER(job_definition.name) LIKE LOWER(#{name})
            ))
        )
    

ORDER BY create_time DESC, id DESC

mapper.update:
UPDATE ifj_instance
SET execution_fence = #{fenceToken},
    start_time = CASE WHEN status IN ('RUNNING', 'PAUSED') THEN NULL ELSE start_time END,
    status = CASE WHEN status IN ('RUNNING', 'PAUSED') THEN 'WAITING' ELSE status END,
    update_time = CURRENT_TIMESTAMP(3)
WHERE root_instance_id = #{rootInstanceId}
  AND status IN ('WAITING', 'RUNNING', 'PAUSED', 'WAITING_EVENT')
  AND EXISTS (
      SELECT 1 FROM ifj_trigger_work_item work_item
      WHERE work_item.root_instance_id = #{rootInstanceId}
        AND work_item.status = 'CLAIMED'
        AND work_item.claim_token = #{claimToken}
        AND work_item.fence_token = #{fenceToken}
        AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)
  )

